<?php require 'includes/bootstrap.php';$slug=(string)($_GET['slug']??'');$p=product_by_slug($slug);if(!$p){http_response_code(404);$pageTitle='المنتج غير موجود';require 'includes/header.php';echo '<section class="section"><div class="empty"><h1>المنتج غير موجود</h1></div></section>';require 'includes/footer.php';exit;}$pageTitle=$p['name'].' | أبشر';require 'includes/header.php';$msg='مرحبًا، أريد الاستفسار عن '.$p['name'];$wa='https://wa.me/'.preg_replace('/\D/','',(string)config('whatsapp_number')).'?text='.urlencode($msg);?><section class="product-page"><div class="product-visual"><div class="placeholder"><span><?=e(u_first($p['brand']??'م'))?></span><small>صورة المنتج</small></div></div><div class="product-info"><div class="badges"><span><?=e($p['brand']??'')?></span><span><?=e($p['availability']??'')?></span></div><h1><?=e($p['name'])?></h1><p class="lead"><?=e($p['short_description']??'')?></p><div class="price"><?=!empty($p['price'])?money($p['price']):e($p['price_label']??'اتصل لمعرفة السعر')?></div><div class="actions"><a class="btn primary" target="_blank" rel="noopener" href="<?=e($wa)?>">اطلب عبر WhatsApp</a><a class="btn" href="tel:<?=e((string)config('phone_number'))?>">اتصل الآن</a></div><div class="trust"><b>ثقة البيانات <?= (int)($p['confidence']??0) ?>%</b> — <?=e($p['source_name']??'إدخال يدوي')?></div></div></section><section class="section two-col"><div><span class="eyebrow">الوصف</span><h2>عن المعدة</h2><p><?=nl2br(e($p['description']??''))?></p></div><div><span class="eyebrow">المواصفات</span><h2>البيانات الفنية</h2><dl class="specs"><?php foreach(($p['specs']??[])as$k=>$v):?><div><dt><?=e((string)$k)?></dt><dd><?=e((string)$v)?></dd></div><?php endforeach;?></dl></div></section><?php require 'includes/footer.php';?>